  `pdf_file` varchar(500) DEFAULT NULL,
  `video_file` varchar(255) DEFAULT NULL,
  `email_subject` varchar(500) DEFAULT NULL,
  `email_template` longtext DEFAULT NULL,
  `case_study_headline` varchar(500) DEFAULT NULL,
  `case_study_summary` varchar(1000) DEFAULT NULL,
  `custom_fields` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`custom_fields`)),
  `webhook_url` varchar(500) DEFAULT NULL,
  `builder_layout` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`builder_layout`)),
  `builder_content_elements` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`builder_content_elements`)),
  `builder_page_data` longtext DEFAULT NULL,
  `webhook_field_mapping` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`webhook_field_mapping`)),
