  `scheduled_publish_date` datetime DEFAULT NULL,
  `webinar_date` datetime DEFAULT NULL,
  `hosted_by` varchar(255) DEFAULT NULL,
  `platform` varchar(255) DEFAULT NULL,
  `webinar_type` varchar(50) DEFAULT 'live',
